	private static Map<String, byte[]> snapshot(Path directory) throws IOException {
		Map<String, byte[]> files = new TreeMap<>();
		try (var paths = Files.walk(directory)) {
			for (Path file : paths.toList()) {
				assertFalse(Files.isSymbolicLink(file));
				String name = file.getFileName().toString();
				if (Files.isRegularFile(file) && !name.equals("lock") && !name.equals("lock.mdb")) {
					files.put(directory.relativize(file).toString(), Files.readAllBytes(file));
				}
			}
		}
		assertTrue(files.containsKey("store.properties"));
		return files;
	}

